package com.example.starter.radio.model;

/**
 * 合成核素。半衰期单位：秒，为衰变计算唯一参数来源。
 */
public record Nuclide(long id, String code, String name, long halfLifeSeconds) {
}

package com.example.starter.radio.model;

/**
 * 活度计（合成数据）。
 */
public record DoseCalibrator(long id, String code, String name) {
}

package com.example.starter.radio.model;

import java.time.LocalDate;

/**
 * 活度计日检记录。deviationRatio 为相对偏差（实测-标称）/标称；
 * 绝对值恰 0.05 判定通过，超过 0.05 当日禁用。
 */
public record DailyCheck(
        long id,
        String requestId,
        String fingerprint,
        long calibratorId,
        LocalDate checkDate,
        double referenceActivityBq,
        double measuredActivityBq,
        double deviationRatio,
        boolean passed) {
}

package com.example.starter.radio.model;

/**
 * 母液批次。initialActivityBq 对应 referenceTimeEpoch（UTC epoch 秒）；
 * remainingActivityBq 对应 remainingTimeEpoch，发药扣减在同一事务内更新。
 */
public record MotherLiquor(
        long id,
        String batchCode,
        long nuclideId,
        double initialActivityBq,
        long referenceTimeEpoch,
        double remainingActivityBq,
        long remainingTimeEpoch,
        String status) {
}

package com.example.starter.radio.model;

/**
 * 处方（合成数据）。prescribedActivityBq 对应给药时刻 administrationTimeEpoch（UTC epoch 秒）。
 */
public record Prescription(
        long id,
        String code,
        long nuclideId,
        double prescribedActivityBq,
        long administrationTimeEpoch) {
}

package com.example.starter.radio.model;

/**
 * 双人核对链记录。checkSeq 为核对次序（1 第一人 / 2 第二人），两名核对人员必须不同。
 */
public record DispensingCheck(
        long id,
        long dispensingId,
        String checker,
        int checkSeq,
        long checkedAtEpoch) {
}

package com.example.starter.radio.model;

/**
 * 发药勾稽台账：母液初始活度 = 分装总量 + 剩余活度 + 衰变残量（均推算至 measuredAtEpoch，UTC epoch 秒）。
 */
public record ReconciliationLedger(
        long id,
        long dispensingId,
        double initialActivityBq,
        double dispensedTotalBq,
        double remainingActivityBq,
        double decayResidualBq,
        boolean balanced,
        long measuredAtEpoch) {
}

package com.example.starter.radio.model;

/**
 * 批次完成后的迟到事件，仅记录不改动业务状态。
 */
public record LateEvent(
        long id,
        long dispensingId,
        String eventType,
        String payload,
        long receivedAtEpoch) {
}

